function download(name,text,type='text/plain;charset=utf-8'){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name.replace(/[\\/:*?"<>|]/g,'_');a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function modal(title,body,wide=false){const el=$('#modal');el.className=wide?'wide':'';el.innerHTML=`<div class="modal-head"><div><span class="micro">PAPERKNOW</span><h2 id="modal-title">${title}</h2></div><button class="icon-btn" data-action="close-modal" aria-label="关闭">${icon('close')}</button></div><div class="modal-body">${body}</div>`;requestReportClose=trackDialogForm(el);if(!el.open)el.showModal();}
